RED.deploy = (function() {

    var deploymentTypes = {
        "rwire": { img: "red/images/crab-animal-crustacean-svgrepo-com.svg" },
        "editor": { img: "red/images/crab-animal-crustacean-svgrepo-com.svg" }
    };

    var deploymentType = "rwire";
    
    // 現在選択されているmruby/cのバージョンを保持する変数
    var currentMrubycVersion = "3.4.0"; 

    function changeDeploymentType(type) {
        deploymentType = type;
        $("#red-ui-header-button-deploy-icon").attr("src", deploymentTypes[type].img);
        $("#red-ui-header-button-deploy .red-ui-deploy-button-content span").first().text(getDeployLabel());
    }
    
    function getDeployLabel() {
        return deploymentType === "rwire" ? "マイコンへ書き込む" : "Webエディタで確認";
    }

    // mruby/cのバージョンを変更した時の処理
    function changeMrubycVersion(version) {
        currentMrubycVersion = version;
        // ボタンのラベルを更新
        $("#red-ui-header-button-version-label").text("mruby/c " + version);
        if (RED.mrubycSettings && typeof RED.mrubycSettings.setVersion === "function") {
            RED.mrubycSettings.setVersion(version);
        }
    }

    async function sendFlow(data) {
        console.log(JSON.stringify({ flows: data }));
        try {
            const makeProjectResponse = await fetch(`https://ceres.epi.it.matsue-ct.ac.jp/rwire/project`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({ flows: data }),
            });

            if (!makeProjectResponse.ok) {
                throw new Error(`HTTP error! status: ${makeProjectResponse.status}`);
            }

            const projectRes = await makeProjectResponse.json();
            console.log("サーバーからの応答:", projectRes);
            
            const projectId = projectRes.data.projectId;
            
            // 選択されたバージョンを使用するように変更
            const mrubycVersion = currentMrubycVersion; 

            const convertResponse = await fetch(`https://ceres.epi.it.matsue-ct.ac.jp/rwire/project/${projectId}/convert`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({
                    version: mrubycVersion,
                }),
            });
            if(!convertResponse.ok)
            {
                alert("変換に失敗しました。フローを確認してください。");
                return ;
            }
            const convertResult = await convertResponse.json();
            
            const res = await fetch("https://ceres.epi.it.matsue-ct.ac.jp/compile/code", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({
                    code: convertResult.data.mainCode,
                }),
            });
            
            if (!res.ok) {
                alert("アップロードに失敗しました");
                return;
            }
            const json = await res.json();
            if(deploymentType === "rwire"){
                window.open(`https://kaniwriter.poporon.org/?id=${json.id}`, '_blank');
            } else if(deploymentType === "editor") {
                window.open(`https://mrbcode.suzune.workers.dev/?id=${projectId}`, '_blank');
            }
            
        } catch (error) {
            console.error("送信エラー:", error);
        }
    }

    function init(options) {
        options = options || {};
        var label = deploymentType === "rwire" ? "マイコンへ書き込む": "Webエディタで確認";

        // RED.mrubycSettingsが既存の場合、そこから初期バージョンを取得
        if (RED.mrubycSettings && typeof RED.mrubycSettings.getVersion === "function") {
            currentMrubycVersion = RED.mrubycSettings.getVersion() || currentMrubycVersion;
        }

        $('<li><span class="red-ui-deploy-button-group button-group">'+
            '<a id="red-ui-header-button-deploy" class="red-ui-deploy-button" href="#">'+ 
            '<span class="red-ui-deploy-button-content">'+
            '<span>'+label+'</span>'+
            '</span>'+
            '<span class="red-ui-deploy-button-spinner hide">'+
            '<img src="red/images/spin.svg"/>'+
            '</span>'+
            '</a>'+
            '<a id="red-ui-header-button-deploy-options" class="red-ui-deploy-button" href="#"><i class="fa fa-caret-down"></i><i class="fa fa-lock"></i></a>'+
            '</span></li>').prependTo(".red-ui-header-toolbar");

        $('<li><span class="red-ui-deploy-button-group button-group">'+
            '<a id="red-ui-header-button-version-options" class="red-ui-deploy-button" href="#">'+
            '<span class="red-ui-deploy-button-content">'+
            '<span id="red-ui-header-button-version-label">mruby/c '+currentMrubycVersion+'</span>'+
            '</span>'+
            ' <i class="fa fa-caret-down"></i>'+
            '</a>'+
            '</span></li>').prependTo(".red-ui-header-toolbar");

        const mainMenuItems = [
            {id:"deploymenu-item-rwire", icon:"red/images/deploy-nodes.svg", label:RED._("deploy.rwire"), sublabel:RED._("deploy.rwireDesc"), onselect:function() { changeDeploymentType("rwire"); }},
            {id:"deploymenu-item-editor", icon:"red/images/deploy-nodes.svg", label:RED._("deploy.webEditor"), sublabel:RED._("deploy.webEditorDesc"), onselect:function() { changeDeploymentType("editor"); }}
        ];
        RED.menu.init({id:"red-ui-header-button-deploy-options", options: mainMenuItems });

        const versionMenuItems = [
            {id:"mrubyc-ver-3.4.0", label:"mruby/c 3.4.0", onselect:function() { changeMrubycVersion("3.4.0"); }},
            {id:"mrubyc-ver-4.0.0", label:"mruby/c 4.0.0", onselect:function() { changeMrubycVersion("4.0.0"); }}
        ];
        RED.menu.init({id:"red-ui-header-button-version-options", options: versionMenuItems });

        $('#red-ui-header-button-deploy').on("click", function(event) {
            event.preventDefault();
            save();
        });
    }

    function save(skipValidation, force) {
        if ($("#red-ui-header-button-deploy").hasClass("disabled")) {
            return; 
        }

        const nns = RED.nodes.createCompleteNodeSet();
        const activeWorkspace = RED.workspaces.active();
        const flow = nns.filter(function(node) {
            if (node.type === "tab" || node.type === "subflow") {
                return node.id === activeWorkspace;
            }
            return node.z === activeWorkspace;
        });
        
        console.log("送信するフローデータ:", flow);
        sendFlow(flow);
    }

    return {
        init: init
    };
})();
